    The algorithm uses a memoization technique to optimize recursive backtracking.
    """

    memo = {}

    def helper(p, t):
        if (p, t) in memo:
            return memo[(p, t)]

        if p == len(pattern) and t == len(text):
            return True
        if p == len(pattern):
            return False
