        match_char = (pattern[p] == text[t] or pattern[p] == '.')

        if p + 1 < len(pattern):
            if pattern[p + 1] == '*':
                # Two cases: we use '*' (current character can occur zero or more times)
                zero_match = helper(p + 2, t)  # '*' means zero occurrences
                one_or_more_match = match_char and helper(p, t + 1)  # Try to match one or more
                result = zero_match or one_or_more_match
            elif pattern[p + 1] == '+':
                # At least one occurrence must be matched
                result = match_char and helper(p, t + 1) or (match_char and helper(p + 2, t))
            else:
                result = match_char and helper(p + 1, t + 1)  # Proceed with both characters matched
        else:
            result = match_char and helper(p + 1, t + 1)  # Last character in pattern

        memo[(p, t)] = result
        return result

    return helper(0, 0)
